<?php use AlbaTech\Core\View; ?>
<div class="welcome-row"><div><h2>Your service catalogue</h2><p>Control availability, homepage promotion and pricing from one place.</p></div><a class="btn btn-primary" href="/admin/services/create"><i class="fa-solid fa-plus"></i> Add service</a></div><section class="panel"><div class="toolbar"><div class="search-box"><i class="fa-solid fa-magnifying-glass"></i><input type="search" id="serviceSearch" placeholder="Search services or categories..."></div><span class="muted-count"><?= count($services) ?> service<?= count($services) === 1 ? '' : 's' ?></span></div><div class="table-wrap"><table id="servicesTable"><thead><tr><th>Service</th><th>Category</th><th>Price display</th><th>Website status</th><th>Homepage</th><th class="actions-col">Actions</th></tr></thead><tbody><?php if (!$services): ?><tr><td colspan="6" class="empty-state">No services found. Create your first service.</td></tr><?php endif; ?><?php foreach ($services as $service): ?><tr data-search="<?= View::escape(strtolower($service['name'].' '.$service['category_name'])) ?>"><td><div class="service-name"><strong><?= View::escape($service['name']) ?></strong><small>/services/<?= View::escape($service['slug']) ?></small></div></td><td><?= View::escape($service['category_name']) ?></td><td><?php if ($service['pricing_type'] === 'quote'): ?><span class="price-label">Contact for price</span><?php else: ?><strong><?= $service['pricing_type'] === 'starting_at' ? 'From ' : '' ?>KSh <?= View::escape(number_format((float)$service['pricing_amount'], 0)) ?></strong><?php endif; ?></td><td><form method="post" action="/admin/services/<?= (int)$service['id'] ?>/toggle" class="inline-form"><input type="hidden" name="_csrf" value="<?= View::escape($csrf) ?>"><button class="toggle-action <?= $service['status'] === 'published' ? 'is-on' : '' ?>" type="submit" title="<?= $service['status'] === 'published' ? 'Click to hide service' : 'Click to publish service' ?>"><span class="toggle-dot"></span><?= $service['status'] === 'published' ? 'On' : 'Off' ?></button></form></td><td><form method="post" action="/admin/services/<?= (int)$service['id'] ?>/feature" class="inline-form"><input type="hidden" name="_csrf" value="<?= View::escape($csrf) ?>"><button class="feature-action <?= (int)$service['is_featured'] ? 'is-featured' : '' ?>" type="submit"><i class="fa-solid fa-star"></i> <?= (int)$service['is_featured'] ? 'Featured' : 'Feature' ?></button></form></td><td class="actions-cell"><a class="icon-action" href="/admin/services/<?= (int)$service['id'] ?>/edit" aria-label="Edit service" title="Edit"><i class="fa-solid fa-pen"></i></a><?php if ($service['status'] === 'published'): ?><a class="icon-action" href="/services/<?= View::escape(rawurlencode($service['slug'])) ?>" target="_blank" rel="noopener" aria-label="View service" title="View public page"><i class="fa-solid fa-arrow-up-right-from-square"></i></a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><div class="table-foot"><i class="fa-solid fa-circle-info"></i> Turning a service off hides it from the public catalogue. Featured services appear on the homepage only while published and in an active category.</div></section><script nonce="<?= View::escape($cspNonce ?? '') ?>">document.getElementById('serviceSearch').addEventListener('input',function(){var q=this.value.toLowerCase();document.querySelectorAll('#servicesTable tbody tr[data-search]').forEach(function(row){row.hidden=!row.dataset.search.includes(q)});});</script>
